import sys

def main():
    import sys
    n, k = map(int, sys.stdin.read().split())

    if n < k or n > k * (2 ** (k - 1)):
        print("NO")
        return

    a = [1] * k
    remaining = n - k

    for i in range(k):
        if remaining == 0:
            break
        increment = min(remaining, 2 ** i)
        a[i] += increment
        remaining -= increment

    if remaining != 0:
        print("NO")
    else:
        print("YES")
        print(" ".join(map(str, a)))

if __name__ == "__main__":
    main()
